arguments.command:
ls -la data/ && python -c "
import h5py
f = h5py.File('data/QLAK-CA1-08.mat','r')
def show(name, obj):
    if isinstance(obj, h5py.Dataset):
        print(name, obj.shape, obj.dtype)
    else:
        print(name+'/', 'GROUP')
f.visititems(show)
"

