arguments.command:
python -c "
import h5py, numpy as np
f = h5py.File('data/QLAK-CA1-08.mat','r')
def s(ref):
    return ''.join(chr(c) for c in f[ref][:].flatten())
envs = [s(r) for r in f['envs'][0]]
for i,r in enumerate(f['blocked'][0]):
    print(i, envs[i], f[r][:].ravel())
"

